static void check(HRESULT h,const char *where){if(FAILED(h)){std::fprintf(stderr,"FIXTURE_FAIL %s code=%08lx\n",where,(unsigned long)h);std::exit(2);}}
static void pump(){MSG m;while(PeekMessageA(&m,nullptr,0,0,PM_REMOVE)){TranslateMessage(&m);DispatchMessageA(&m);}}
static void gate(const char *dir,const char *name){char path[2048];std::snprintf(path,sizeof(path),"%s\\%s",dir,name);DWORD begin=GetTickCount();while(GetFileAttributesA(path)==INVALID_FILE_ATTRIBUTES){if(GetTickCount()-begin>90000)std::exit(3);pump();Sleep(5);}}
static void wait(ID3D11Device *d,ID3D11DeviceContext *c){D3D11_QUERY_DESC desc{D3D11_QUERY_EVENT,0};ID3D11Query *q=nullptr;check(d->CreateQuery(&desc,&q),"event");c->End(q);c->Flush();DWORD start=GetTickCount();for(;;){HRESULT h=c->GetData(q,nullptr,0,0);check(h,"event completion");if(h==S_OK)break;if(GetTickCount()-start>20000)std::exit(4);pump();Sleep(1);}q->Release();}
static ID3DBlob *compile(const char *source,const char *profile){ID3DBlob *b=nullptr,*errors=nullptr;HRESULT h=D3DCompile(source,std::strlen(source),nullptr,nullptr,nullptr,"main",profile,D3DCOMPILE_ENABLE_STRICTNESS,0,&b,&errors);if(errors){if(FAILED(h))std::fwrite(errors->GetBufferPointer(),1,errors->GetBufferSize()<2048?errors->GetBufferSize():2048,stderr);errors->Release();}check(h,"shader");return b;}
static void pixels(ID3D11Device *d,ID3D11DeviceContext *c,ID3D11Texture2D *target,const char *label){D3D11_TEXTURE2D_DESC desc{};target->GetDesc(&desc);desc.Usage=D3D11_USAGE_STAGING;desc.BindFlags=0;desc.CPUAccessFlags=D3D11_CPU_ACCESS_READ;desc.MiscFlags=0;ID3D11Texture2D *read=nullptr;check(d->CreateTexture2D(&desc,nullptr,&read),"pixel staging");c->CopyResource(read,target);wait(d,c);D3D11_MAPPED_SUBRESOURCE map{};check(c->Map(read,0,D3D11_MAP_READ,0,&map),"pixel map");unsigned green=0;unsigned long long hash=14695981039346656037ull;for(unsigned y=0;y<64;y++)for(unsigned x=0;x<256;x++){unsigned char v=((unsigned char*)map.pData)[y*map.RowPitch+x];hash=(hash^v)*1099511628211ull;if(x%4==1&&v>=250)green++;}c->Unmap(read,0);read->Release();std::printf("FIXTURE_PIXELS %s green=%u hash=%016llx\n",label,green,hash);std::fflush(stdout);}
